function pendingKey(kind,body){let raw=null;try{raw=localStorage.getItem('hq-pending-'+kind)}catch{}if(raw){let p;try{p=JSON.parse(raw)}catch{localStorage.removeItem('hq-pending-'+kind);p=null}if(p){if(JSON.stringify(p.body)!==JSON.stringify(body))throw new Error('A previous submission has no confirmed receipt. Restore the saved request before changing it.');return p.key}}const key=crypto.randomUUID();try{localStorage.setItem('hq-pending-'+kind,JSON.stringify({key,body}))}catch{}return key}
