async function knowledgeSubmission(d){const {mountKnowledgeSubmission}=await import('./knowledge-submit.mjs');showDetail('Submit a knowledge candidate',`<p class="muted">This writes your summary and source reference to the configured local Librarian inbox. The Librarian reviews it before updating the wiki.</p><form id="knowledge-form"><label>Title<input name="title" required maxlength="160"></label><label>Project-relative source artifact<input name="source_path" required maxlength="500"></label><label>Verified summary<textarea name="summary" rows="7" required maxlength="8000"></textarea></label><p role="alert"></p><button type="submit" class="primary">Submit to Librarian</button></form>`);mountKnowledgeSubmission({form:$('#knowledge-form'),project:d.office_project,taskId:d.task.id,api,onConfirmed:()=>{toast('Submission confirmed · curation pending');$('#detail').close()}})}
