async function editLessons(d){const rows=(await api('lessons')).filter(l=>l.task_id===d.task.id);showDetail('Learned corrections',`<p class="muted">Task ${esc(d.task.id)} · standing rules apply to subsequent office work for this agent and project.</p><div id="lesson-list">${rows.map(l=>`<article class="card"><p>${esc(l.text)}</p><small>${esc(l.scope)} · ${l.enabled?'Enabled':'Disabled'}</small><button data-lesson="${l.id}">Edit</button></article>`).join('')}</div><form id="lesson-form"><label>Correction<textarea id="lesson-text" rows="5" required></textarea></label><label>Scope<select id="lesson-scope"><option value="one-off">One-off feedback</option><option value="standing">Standing rule</option></select></label><label><input id="lesson-enabled" type="checkbox" checked> Enabled</label><button class="primary">Save correction</button></form><p class="muted">Saving one-off feedback records it. Use Request revision to start follow-up work.</p>`);let editing;document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{editing=rows.find(l=>l.id===b.dataset.lesson);$('#lesson-text').value=editing.text;$('#lesson-scope').value=editing.scope;$('#lesson-enabled').checked=editing.enabled});$('#lesson-form').onsubmit=async e=>{e.preventDefault();try{await api('lessons',{id:editing?.id,profile:d.task.assignee,project:d.office_project,task_id:d.task.id,text:$('#lesson-text').value,scope:$('#lesson-scope').value,enabled:$('#lesson-enabled').checked});toast('Correction saved');await editLessons(d)}catch(e){toast(e.message)}}}
function automationRows(dept,q=''){
 return teamInventory.groups.filter(g=>(!dept||g.department===dept)&&(!q||(g.name+' '+g.description).toLowerCase().includes(q.toLowerCase()))).map(g=>`<button class="agent-row" data-automation="${esc(g.id)}"><span>${esc(g.name)}<small>${esc(g.state)} · ${g.enabled_count}/${g.jobs.length} schedules enabled</small></span><span class="initial">◷</span></button>`).join('');
}
function bindAutomations(root){root.querySelectorAll('[data-automation]').forEach(b=>b.onclick=()=>showAutomation(b.dataset.automation));}
function scheduleMetadata(rows){return rows.map(r=>`<article class="card"><h3>${esc(r.name)}</h3><p>${r.enabled?'Enabled':'Paused'} · ${esc(r.schedule||'Schedule unavailable')}</p><p>Last run: ${r.last_run_at?esc(new Date(r.last_run_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})):'Not recorded'} · ${esc(r.last_status||'No result recorded')}</p>${r.enabled?'<p>Next: '+esc(r.next_run_at?new Date(r.next_run_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'Not recorded')+'</p>':''}</article>`).join('');}
function showAutomation(id){const g=teamInventory.groups.find(g=>g.id===id);if(!g)return;const owner=state.profiles.find(p=>p.id===g.owner_profile);showDetail(g.name,`<p>${esc(g.description)}</p><p>${esc(g.state)} · Coordinated by ${esc(owner?.name||g.owner_profile)}</p><p class="muted">Existing scheduled work · last recorded results. Enabled schedules are not a guarantee of successful execution or delivery.</p>${scheduleMetadata(g.jobs)}${owner?'<button id="automation-owner">Open '+esc(owner.name)+' ↗</button>':''}`,'AUTOMATION');if(owner)$('#automation-owner').onclick=()=>{$('#detail').close();office.select(owner)};}
async function refreshTeamInventory(){teamInventory=await api('team');return teamInventory;}
async function renderAgents(dept){
 $('#panel-content').innerHTML=`<div class="section-heading"><h2>Your team</h2><span>${state.profiles.filter(p=>p.installed).length} agents</span></div><button id="department-setup">Department setup interview</button><input class="search" id="agent-search" aria-label="Search agents" placeholder="Find an agent or automation"><div id="agent-rows"></div>`;
 const draw=q=>{if(!$('#agent-rows'))return;$('#agent-rows').innerHTML=state.profiles.filter(p=>(!dept||p.department===dept)&&(!q||(p.name+' '+p.id+' '+(p.role||'')).toLowerCase().includes(q.toLowerCase()))).map(p=>`<button class="agent-row" data-agent="${p.id}"><span>${esc(p.name)}<small>${esc(p.department_name)} · ${p.installed?esc(p.model):'Not installed'}</small></span><span class="initial">${esc(p.name[0])}</span></button>`).join('')+`<h3>Existing automations</h3>${teamInventory.stale||teamInventory.read_errors.length?'<p class="inline-notice">Some scheduler metadata is unavailable. Showing the last observed inventory.</p>':''}${automationRows(dept,q)}<button id="other-schedules">Other active schedules (${teamInventory.other_routines.filter(r=>!dept||state.profiles.find(p=>p.id===r.profile)?.department===dept).length}) ↗</button>`;$('#agent-rows').querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>office.select(state.profiles.find(p=>p.id===b.dataset.agent)));bindAutomations($('#agent-rows'));$('#other-schedules').onclick=()=>showDetail('Other active schedules',scheduleMetadata(teamInventory.other_routines.filter(r=>!dept||state.profiles.find(p=>p.id===r.profile)?.department===dept))||'<p>No other active schedules.</p>','SCHEDULER INVENTORY');};
 draw('');$('#agent-search').oninput=e=>draw(e.target.value);$('#department-setup').onclick=()=>departmentSetup(dept||activeDepartment).catch(e=>toast(e.message));
 try{await refreshTeamInventory();if(tab==='agents')draw($('#agent-search')?.value||'')}catch(e){toast(e.message)}
}

async function agentActivity(p){showDetail(p.name,'<p class="muted">Reading recorded activity…</p>','AGENT ACTIVITY');const data=await api('profiles/'+p.id+'/activity');if(!$('#detail').open||$('#detail-label').textContent!=='AGENT ACTIVITY'||$('#detail-title').textContent!==p.name)return;const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-(6-i));return {date,count:data.events.filter(e=>e.at*1000>=date.getTime()&&e.at*1000<date.getTime()+86400000).length}}),max=Math.max(1,...days.map(d=>d.count));$('#detail-content').innerHTML='<p class="muted">'+esc(data.scope)+'</p><h3>Recorded events · last seven days</h3><div class="activity-chart">'+days.map(d=>`<div><strong>${d.count}</strong><span style="height:${Math.max(2,d.count/max*90)}px" aria-hidden="true"></span><small>${d.date.toLocaleDateString(undefined,{weekday:'short'})}</small></div>`).join('')+'</div><h3>Current work and history</h3>'+ (scopeItems(items,{profile:p.id}).map(boardCard).join('')||'<p>No work records.</p>')+'<details><summary>Event timeline</summary>'+data.events.map(e=>'<p class="activity-event"><time>'+new Date(e.at*1000).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})+'</time> '+esc(e.kind)+'</p>').join('')+'</details>';bindTasks($('#detail-content'))}
function agentSettings(p){showDetail(p.name,`<p class="eyebrow">${esc(p.department_name)} · ${esc(p.id)}</p><form id="profile-settings"><label>Display name<input name="name" value="${esc(p.name)}" maxlength="80" required></label><label>Role description<textarea name="role" maxlength="1200" rows="3">${esc(p.role||'')}</textarea></label><div class="fields"><label>Default model<input name="model" list="configured-models" value="${esc(p.model||'')}" required></label><label>Provider<input name="provider" value="${esc(p.provider||'')}" required></label></div><label>Default reasoning<select name="effort">${['low','medium','high','xhigh','max','ultra'].map(x=>`<option ${p.effort===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="muted">Saved model defaults apply to future Hermes runs. Task and routine overrides take precedence. The role description is a display label; edit Brief to change work instructions.</p><button class="primary">Save profile settings</button></form><div class="actions"><button id="agent-brief">Work brief</button><button id="agent-skills">Skills and tools</button></div><p class="muted">${p.fallback_enabled?'Execution blocked: automatic provider fallback is enabled.':'Automatic paid-provider fallback disabled.'} Existing runtime permissions remain in force.</p>`,'HERMES PROFILE');$('#agent-brief').onclick=()=>editBrief(p);$('#agent-skills').onclick=()=>editSkills(p).catch(e=>toast(e.message));modelControl($('#profile-settings').elements.model,$('#profile-settings').elements.provider,()=>p.id,false);$('#profile-settings').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const updated=await api('profiles/settings',{profile:p.id,...Object.fromEntries(new FormData(e.target))});Object.assign(p,updated);if(selected?.id===p.id){$('#chat-title').textContent=p.name;railHeader(p.department)}quickHint();toast('Profile settings saved for subsequent runs');$('#detail').close()}catch(e){toast(e.message)}finally{button.disabled=false}}}

async function editSkills(p){const d=await api('skills?profile='+p.id);$('#detail-content').innerHTML=`<p class="muted">${esc(d.review_policy)}</p>${d.skills.map(s=>`<article class="card"><h3>${esc(s.name)}</h3>${status(s.enabled?'enabled':'disabled')}<button data-skill="${esc(s.name)}" ${!s.enabled&&!s.enable_reviewed?'disabled':''}>${s.enabled?'Disable for subsequent runs':'Enable reviewed skill'}</button></article>`).join('')||'<p>No installed skills assigned to this profile.</p>'}`;document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=async()=>{try{const skill=d.skills.find(s=>s.name===b.dataset.skill);await api('skills/toggle',{profile:p.id,name:skill.name,enabled:!skill.enabled});toast('Skill assignment saved');await editSkills(p)}catch(e){toast(e.message)}})}
async function departmentSetup(dept){const [rows,{setupView}]=await Promise.all([api('departments'),import('./setup-view.mjs')]);showDetail('Department setup',`<label>Department<select id="setup-dept">${state.departments.map(d=>`<option value="${d.id}" ${dept===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><div id="setup-workspace"></div>`);const draw=()=>{const department=state.departments.find(d=>d.id===$('#setup-dept').value);setupView($('#setup-workspace'),{department,existing:rows.find(r=>r.id===department.id)?.brief,onCancel:()=>$('#detail').close(),onAsk:async(prompt,withSkills=false)=>{const p=departmentLead(state.profiles,department.id);if(withSkills){try{const catalog=await api('skills?profile='+p.id);prompt+='\n\nInstalled lead skill inventory (metadata only):\n'+JSON.stringify(catalog.skills.map(s=>({name:s.name,enabled:s.enabled,reviewed_for_enable:!!s.enable_reviewed})));}catch(e){toast(e.message);return}}$('#detail').close();office.focus(p.department,false);await openChat(p);$('#chat-input').value=prompt;saveChatDraft()},onSave:async brief=>{try{await api('departments',{id:department.id,brief});toast('Department brief saved for subsequent tasks');$('#detail').close()}catch(e){toast(e.message);throw e}}})};$('#setup-dept').onchange=draw;draw()}


async function editBrief(p){try{const d=await api('briefs?profile='+p.id);$('#detail-content').innerHTML=`<label>Brief for subsequent office conversations<textarea id="brief-text" rows="12">${esc(d.text)}</textarea></label><button id="save-brief" class="primary">Save brief</button><p class="muted">Existing profile safety and authority rules still apply.</p>`;$('#save-brief').onclick=async()=>{await api('briefs',{profile:p.id,text:$('#brief-text').value});toast('Brief saved for subsequent conversations')}}catch(e){toast(e.message)}}
function rememberChat(){sessionStorage.setItem('hq-navigation',JSON.stringify({project:activeProject,profile:selected?.id,conversation:conversation?.id||null}))}
async function openChat(p,sid){if(!p)throw new Error('This agent is not enrolled in Office');if(sid===undefined){try{const saved=JSON.parse(sessionStorage.getItem('hq-navigation')||'null');if(saved?.project===activeProject&&saved?.profile===p.id&&Object.hasOwn(saved,'conversation'))sid=saved.conversation}catch{}}saveChatDraft();$('#task-project').value=activeProject;const version=++chatVersion;streamText='';selected=p;greeting?.show(p);activeDepartment=p.department;connectorDock?.update(connections,p.department);if(feedAgent&&feedAgent!==p.id){feedAgent='';$('#feed-agent').value=''}$('#quick-department').value=p.department;$('#task-department').value=p.department;profileOptions();$('#task-profile').value=p.id;quickHint();conversation=null;currentRun=null;updateQuestion();chatDraftKey=activeProject+':'+p.id;sessionStorage.setItem('hq-navigation',JSON.stringify({project:activeProject,profile:p.id,conversation:sid??null}));$('#agent-rail').hidden=false;document.body.classList.add('has-rail');railHeader(p.department);$('#chat-profile').textContent=p.department_name;$('#chat-title').textContent=p.name;$('#messages').innerHTML='<p class="muted">Opening conversation…</p>';$('#chat-status').textContent='';$('#chat-input').value='';$('#stream').textContent='';$('#chat-model').value='';$('#chat-provider').value='';$('#chat-effort').value='';restoreChatDraft();if(!$('#chat').open)$('#chat').show();$('#agent-actions').innerHTML='<button id="agent-new-task">Task ↗</button><button id="agent-brief-inline">Brief</button><button id="agent-skills-inline">Skills</button><button id="agent-activity">Activity</button><button id="agent-workflow" aria-controls="workflow-drawer">Workflow</button><button id="agent-settings">Settings</button>';$('#agent-new-task').onclick=openComposer;$('#agent-workflow').onclick=e=>workflowDrawer?.open({kind:'agent',profile:p.id},e.currentTarget);$('#chat-command').hidden=true;$('#agent-brief-inline').onclick=()=>{showDetail(p.name,'','AGENT BRIEF');editBrief(p)};$('#agent-skills-inline').onclick=()=>{showDetail(p.name,'','ASSIGNED SKILLS');editSkills(p).catch(e=>toast(e.message))};$('#agent-settings').onclick=()=>agentSettings(p);$('#agent-activity').onclick=()=>agentActivity(p).catch(e=>toast(e.message));renderAgentRoutines(p);const list=(await api('conversations')).filter(c=>c.profile===p.id&&c.project===activeProject);if(version!==chatVersion)return;conversation=sid===null?null:sid?list.find(c=>c.id===sid):list.reduce((latest,c)=>Number(c.created_at)>Number(latest?.created_at||0)?c:latest,null);rememberChat();if(sid&&!conversation){toast('Choose this conversation’s project to open it.');}$('#conversation-list').innerHTML='<option value="">New conversation</option>'+list.map(c=>`<option value="${esc(c.id)}">${esc(c.title)} · ${new Date(c.created_at*1000).toLocaleDateString()}</option>`).join('');$('#conversation-list').value=conversation?.id||'';$('#conversation-list').onchange=()=>{if(!$('#conversation-list').value){conversation=null;rememberChat();currentRun=null;updateQuestion();$('#messages').innerHTML=welcome(p);$('#chat-status').textContent=projectName()}else openChat(p,$('#conversation-list').value).catch(e=>toast(e.message))};if(conversation)await loadMessages();else $('#messages').innerHTML=welcome(p);if(version!==chatVersion)return;$('#chat-status').textContent=projectName()+' · '+(conversation?'Saved conversation':'Starts when you send');currentRun=conversation?runs.filter(r=>r.conversation===conversation.id&&!['completed','failed','interrupted','cancelled'].includes(r.status)).at(-1):null;const pending=conversation&&localStorage.getItem('hq-pending-chat-'+conversation.id);if(pending){const b=JSON.parse(pending).body;$('#chat-input').value=b.prompt;$('#chat-model').value=b.model||'';$('#chat-provider').value=b.provider||'';$('#chat-effort').value=b.effort||'';$('#chat-status').textContent='Unconfirmed message restored; retry keeps its original key.'}updateQuestion();if(tab==='board')renderBoard();}
async function loadMessages(){if(!conversation)return;const id=conversation.id;const d=await api('conversations/'+id+'/messages');if(conversation?.id!==id)return;const rows=d.messages||d.data||[],messages=$('#messages'),atEnd=messages.scrollHeight-messages.scrollTop-messages.clientHeight<50;const html=visibleMessages(rows).map(m=>`<div class="message ${esc(m.role)}"><small>${m.role==='user'?'YOU':esc(selected?.name||'AGENT')}</small>${messageHTML(m.content)}</div>`).join('')||welcome(selected);if(messages.dataset.renderedFor!==id||messages._renderedHTML!==html){messages.innerHTML=html;messages._renderedHTML=html;messages.dataset.renderedFor=id;if(atEnd)messages.scrollTop=messages.scrollHeight;}}
$('#chat-form').onsubmit=async e=>{e.preventDefault();if(await officeCommand($('#chat-input').value))return;const button=e.submitter||$('#chat-form button.primary'),version=chatVersion,person=selected,project=activeProject;let target=conversation;button.disabled=true;const body={prompt:$('#chat-input').value};if($('#chat-model').value){body.model=$('#chat-model').value;body.provider=$('#chat-provider').value}if($('#chat-effort').value)body.effort=$('#chat-effort').value;try{if(!person)throw new Error('Choose an agent');if(!target){const kind='conversation-'+project+'-'+person.id,request={profile:person.id,project,title:person.name};target=await api('conversations',request,{key:pendingKey(kind,request)});clearPending(kind);if(version===chatVersion){conversation=target;rememberChat()}}const key=pendingKey('chat-'+target.id,body);const run=await api('conversations/'+target.id+'/prompt',body,{key});clearPending('chat-'+target.id);if(version===chatVersion){currentRun=run;$('#chat-input').value='';saveChatDraft();$('#chat-status').textContent='Accepted by '+person.name+' · '+run.id;streamText='';await refresh()}else toast('Message accepted by '+person.name)}catch(err){if(target&&([400,403,404,422].includes(err.status)||err.code==='conversation_busy'))clearPending('chat-'+target.id);if(version===chatVersion)$('#chat-status').textContent=err.message;else toast(err.message)}finally{button.disabled=false}};

async function officeCommand(text){const command=parseOfficeCommand(text);if(!command)return false;const person=selected,project=activeProject,version=chatVersion,box=$('#chat-command');if(!person)return true;box.hidden=false;box.innerHTML='<p>Preparing Office action…</p>';try{let title,description,execute;const mutate=async(path,body)=>{const kind='command-'+person.id+'-'+project+'-'+command.kind+'-'+command.id+'-'+command.action,key=pendingKey(kind,body);try{const result=await api(path,body,{key});clearPending(kind);return result}catch(error){if([400,403,404,422].includes(error.status))clearPending(kind);throw error}};if(command.kind==='routine'){const rows=await api('routines');if(version!==chatVersion)return true;const routine=rows.find(r=>r.id===command.id&&r.profile===person.id&&r.office_project===project);if(!routine)throw new Error('This routine is not in the selected agent and project.');if(command.action==='run'&&(routine.paused||routine.enabled===false||routine.state==='paused'))throw new Error('Resume this routine before running it.');if(command.action==='edit'){editRoutine(routine);box.hidden=true;return true}title=command.action[0].toUpperCase()+command.action.slice(1)+' routine';description=(routine.name||routine.id)+' · '+person.name;execute=()=>mutate('routines/'+command.action,{id:routine.id,profile:person.id});}else if(command.kind==='approval'){const rows=await api('approvals'),run=rows.find(r=>r.profile===person.id&&r.project===project&&(r.pending_approvals||[]).some(a=>(a.id||a.request_id)===command.id));if(!run)throw new Error('No matching pending request in this agent and project.');const request=run.pending_approvals.find(a=>(a.id||a.request_id)===command.id);title=command.action==='approve'?'Approve once':'Reject request';description=JSON.stringify(request);execute=()=>mutate('runs/'+run.id+'/approval',{request_id:command.id,choice:command.action==='approve'?'once':'deny'});}else{const item=items.find(t=>t.kind==='task'&&t.id===command.id&&t.profile===person.id&&t.project===project);if(!item)throw new Error('Select the task’s agent and project before revising it.');const detail=await api('tasks/'+item.board+'/'+item.id);if(!detail.office_owned)throw new Error('This task was not admitted through Office.');title='Create revision task';description=item.title+'\n\nFeedback: '+command.feedback;execute=()=>mutate('tasks/'+item.id+'/revise',{feedback:command.feedback});}if(version!==chatVersion)return true;box.innerHTML='<span class="eyebrow">OFFICE ACTION</span><h3>'+esc(title)+'</h3><pre>'+esc(description)+'</pre><div class="actions"><button id="command-cancel">Cancel</button><button id="command-execute" class="primary">'+esc(title)+'</button></div>';$('#command-cancel').onclick=()=>box.hidden=true;$('#command-execute').onclick=async e=>{if(version!==chatVersion)return;e.target.disabled=true;try{await execute();if(version===chatVersion){box.hidden=true;$('#chat-input').value='';saveChatDraft()}await refresh();toast('Office action confirmed')}catch(error){toast(error.message);if(e.target.isConnected)e.target.disabled=false}}}catch(error){if(version===chatVersion)box.innerHTML='<p>'+esc(error.message)+'</p>'}return true}
