 $('#company-open').onclick=showCompany;$('#quick-form').onsubmit=e=>{e.preventDefault();openComposer()};$('#quick-expand').onclick=()=>{openComposer();$('#composer').classList.add('expanded');$('#task-form textarea[name=prompt]').rows=16};$('#quick-input').oninput=()=>{quickHint();$('#quick-input').style.height='auto';$('#quick-input').style.height=Math.min(220,$('#quick-input').scrollHeight)+'px'};$('#task-form [name=prompt]').oninput=e=>{$('#quick-input').value=e.target.value;quickHint()};$('#quick-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();openComposer()}};$('#quick-repeat').onclick=()=>{openComposer();$('#task-form details').open=true;$('#repeat-cadence').focus()};
 let previewTimer;const updatePreview=()=>{clearTimeout(previewTimer);previewTimer=setTimeout(()=>runtimeSchedulePreview($('#task-profile').value,$('#repeat-schedule').value,$('#repeat-preview')),350)};$('#repeat-schedule').oninput=updatePreview;$('#task-profile').onchange=updatePreview;const repeat=()=>{const c=$('#repeat-cadence').value;if(c&&c!=='custom'){try{const r=schedulePreview(c,$('#repeat-time').value);$('#repeat-schedule').value=r.expression;$('#repeat-preview').textContent=r.label+' · '+Intl.DateTimeFormat().resolvedOptions().timeZone}catch(e){$('#repeat-preview').textContent=e.message}}else if(!c){$('#repeat-schedule').value='';$('#repeat-preview').textContent='One task'}updatePreview()};$('#repeat-cadence').onchange=repeat;$('#repeat-time').onchange=repeat;
